examples.erb:
@REF_PRINTL
PRINTL Hello
RETURN

@REF_PRINTVL
PRINTVL "りんご", 2 + 3, "個"
RETURN

@REF_PRINTSL
PRINTSL "りんご" + "5個"
RETURN

@REF_PRINTFORML
PRINTFORML りんご{2 + 3}個
RETURN

@REF_PRINTFORMSL
PRINTFORMSL "りんご{2 + 3}個"
RETURN

@REF_REUSELASTLINE
PRINTL 固定
REUSELASTLINE 読込中
REUSELASTLINE 完了{2 + 3}
PRINTL 次へ
RETURN

@REF_DRAWLINE
DRAWLINE
RETURN

@REF_BARL
BARL 3, 10, 10
RETURN

@REF_PRINTBUTTON
PRINTBUTTON "進む", 7
PRINTL
INPUT
PRINTFORML 選択={RESULT}
RETURN

@REF_PRINTBUTTONC
PRINTBUTTONC "進む", 7
PRINTL
INPUT
PRINTFORML 選択={RESULT}
RETURN

@REF_PRINTBUTTONLC
PRINTBUTTONLC "進む", 7
PRINTL
INPUT
PRINTFORML 選択={RESULT}
RETURN

@REF_PRINTPLAINFORM
PRINTPLAINFORM [1] 個数={2 + 3}
PRINTL
RETURN

@REF_DRAWLINEFORM
DRAWLINEFORM =-
RETURN

@REF_PRINTDATAL
PRINTDATAL LOCAL
DATAFORM りんご{2 + 3}個
ENDDATA
PRINTFORML 選択番号={LOCAL}
RETURN

@REF_PRINTCPERLINE
PRINTCPERLINE LOCAL
PRINTFORML 列数={LOCAL}
RETURN

@REF_SKIPDISP
SKIPDISP 1
PRINTL 出ない行
SKIPDISP 0
PRINTFORML 状態={RESULT}
RETURN
